    "content": "本出口增速在8月份略有放缓，但仍保持高水平，其中对美国出口增幅领先。财务省周三公布的数据显示，当月出口额同比增长19.3%，增速较7月的23.2%有所放缓。媒体调查经济学家的预估中值位增长18.4%。进口增长28%，高于经济学家预测的26.3%。未经调整的贸易逆差扩大至1.1万亿日元，高于7月修正后的逆差6，383亿日元，为连续第四个月出现逆差。按目的地划分，对美国的出口增长24.9%，对中国和欧洲的出口分别增长20.6%和11%。（新浪财经）"
