    "description": "36氪获悉，中信证券研报称，2026年9月10日，国新办发布会宣布《金融强国建设“十五五”规划》正式出台，四部门有关负责人同台解读。金融监管呈“存量出清+资本补充+反内卷”三线并进。保险业定位升格、任务细化、政策体系健全，形成“稳功能、强治理、扩服务、引长钱”四位一体。行业短期保费承压，经营质效有望持续改善，头部机构竞争优势进一步凸显，发展逻辑从“规模驱动”切换为“资本回报驱动”，板块有望在市场贝塔属性之外进一步凸显红利属性。",
    "content": "36氪获悉，中信证券研报称，2026年9月10日，国新办发布会宣布《金融强国建设“十五五”规划》正式出台，四部门有关负责人同台解读。金融监管呈“存量出清+资本补充+反内卷”三线并进。保险业定位升格、任务细化、政策体系健全，形成“稳功能、强治理、扩服务、引长钱”四位一体。行业短期保费承压，经营质效有望持续改善，头部机构竞争优势进一步凸显，发展逻辑从“规模驱动”切换为“资本回报驱动”，板块有望在市场贝塔属性之外进一步凸显红利属性。"
