    "description": "36氪获悉，中信建投证券研报认为，国防军工板块业绩自2025年触底以来持续回升，需求恢复已连续多个季度体现至报表端，2026年上半年板块利润增速显著上台阶，复苏正从结构性走向全面性。在2027年建军百年背景下，2025至2027年行业向好趋势确定性强，当前正处于“十四五”收官与“十五五”规划交替的关键窗口。随着“十五五”规划装备目录逐步明确，规模化订单下达渐行渐近，板块已进入基本面全面复苏新周期。",
