    "content": "新华社利马9月15日电（记者王植樱 廖思维）以“多边主义与人权”为主题的第三届中拉人权圆桌会15日在秘鲁首都利马举办。来自中国和23个拉美加勒比国家的近200名高级官员、前政要、专家学者及有关社会组织、媒体、智库代表围绕和平发展与人权治理、中拉务实合作与人权发展、中拉人权文明交流互鉴等议题进行交流。 秘鲁国立圣马尔科斯大学校长赫里·拉蒙说，中拉人权圆桌会提供了交流经验和分享思考的机会，希望借此对话平台提出新的倡议，为促进各国人民的教育、发展与福祉作出贡献。 中国人权研究会副会长、中国人民大学校长马怀德表示，中拉同属…"
