    "content": "新华社布宜诺斯艾利斯9月15日电（记者张铎）阿根廷外长巴勃罗·基尔诺15日通过其个人社交媒体账号公布一份阿根廷外交部声明，表示强烈抵制英国政府发布在马尔维纳斯群岛（简称马岛，英国称福克兰群岛）开展商业活动的指南。 声明称，马岛及周边海域属于阿根廷领土，英国政府单方面行为已违反联合国相关决议。阿政府将动用包括外交、经济和法律在内的所有手段，让非法开采马岛自然资源者承担责任。与此同时，阿根廷愿意同英国恢复双边谈判，解决主权争议。 英国政府15日发布了一份在马岛开展商业活动的官方指南《与福克兰群岛开展商业活动》，称阿根廷…"
