    "content": "新华社维也纳9月15日电（记者孟凡宇 刘海燕）在国际原子能机构第70届大会期间，中国14日主办“聚力小堆创新，共创核美家园”主题边会，聚焦加强全球范围内小型模块化反应堆（小堆）国际合作，推动技术创新、标准协调、能力建设及相关推广应用，为全球气候治理和可持续发展提供助力。 中国国家原子能机构主任单忠德在会上表示，中国将核能作为建设新型能源体系、实现碳达峰碳中和目标的重要选项，依托完备的核工业创新链、产业链、人才链，成为小堆开发部署的先行者和开拓者之一。 单忠德说，未来中国将倡导科技创新合作，夯实小堆产业发展底座，同时…"
