    "content": "新华社济南9月16日电（记者顾天成、张武岳）9月16日，引力一号遥三运载火箭在我国东海海域点火升空，成功将搭载的8颗千帆星座组网卫星与1颗超高速无线通信技术试验卫星顺利送入预定轨道，发射任务取得圆满成功。 记者从火箭研制方东方空间（山东）科技有限公司获悉，此次任务创下我国单次海上发射载荷重量和轨道高度新高，净载荷重量超3吨，入轨高度约800公里，验证了海上发射模式对中大型卫星载荷任务的适应能力。 引力一号目前已累计实施四次海上发射，均获成功。据悉，本次任务是引力一号首次开展大型低轨卫星互联网星座组网发射。火箭采用堆…"
