    "content": "新华社华盛顿9月15日电（记者杨伶 熊茂伶）美国肯尼迪表演艺术中心董事会15日投票决定立即关闭该中心进行翻修。投票前不久，一名联邦法官发布命令，驳回肯尼迪中心董事会将美国总统特朗普的名字再次添加到中心大楼外墙上的提议。 哥伦比亚特区联邦地区法院法官克里斯托弗·库珀15日中午发布命令说：“未经国会批准，被告不得在肯尼迪中心为特朗普总统或任何其他人或任何事物设立纪念碑。董事会的决议违背了联邦法院的命令和国会颁布的法令。” 当天稍晚，肯尼迪中心董事会召开会议，投票决定立即关闭该中心进行翻修。美国公共广播公司报道说，此前肯…"
