    "description": "新华社华盛顿9月15日电（记者杨伶 熊茂伶）美国全国广播公司15日援引知情人士的话报道，肯尼迪表演艺术中心董事会当天投票决定立即关闭该中心进行翻新。 投票前不久，哥伦比亚特区联邦地区法院法官克里斯托弗·库珀驳回肯尼迪中心董事会将美国总统特朗普的名字再次添加到中心建筑外墙上的提议。按照董事会的说法，加名是让该中心免于破产的必要举措。",
    "content": "新华社华盛顿9月15日电（记者杨伶 熊茂伶）美国全国广播公司15日援引知情人士的话报道，肯尼迪表演艺术中心董事会当天投票决定立即关闭该中心进行翻新。 投票前不久，哥伦比亚特区联邦地区法院法官克里斯托弗·库珀驳回肯尼迪中心董事会将美国总统特朗普的名字再次添加到中心建筑外墙上的提议。按照董事会的说法，加名是让该中心免于破产的必要举措。"
