    "content": "新华社华盛顿9月15日电（记者黄强 徐剑梅）据美联社15日报道，美国政府正从欧洲和中东国家撤回数千万美元的军事援助资金，转而支持部分中南美洲国家。 报道说，美国国务院当天通知国会，将把原定提供给斯洛伐克、北马其顿、突尼斯和伊拉克的5200万美元“外国军事融资”，调拨给巴拿马、秘鲁、厄瓜多尔和哥伦比亚。美政府“外国军事融资”项目以赠款或贷款形式提供融资，供受援国采购美国军事装备和相关服务。 美国务卿鲁比奥上周访问哥伦比亚、厄瓜多尔和秘鲁，并承诺提供额外支持。美国务院声称，军援资金分配状况“不符合本届政府将西半球列为优…"
