    "content": "新华社马德里9月15日电（记者陈雨峥 谢宇智）西班牙政府15日宣布，针对意大利入境人员的边境检查措施再延长15天，以回应意大利方面第二次延长针对西班牙入境人员的边境检查措施。 据西班牙埃菲社报道，西班牙内政部当日表示，相关边境管控措施再延长15天至10月8日，并将视情况作调整。西班牙已将这一决定通报欧盟。 当日早些时候，意大利政府宣布，鉴于存在国内安全风险以及潜在的恐怖主义渗透威胁，将针对西班牙入境人员的边境检查措施再延长15天。西班牙外交大臣何塞·曼努埃尔·阿尔瓦雷斯当日接受媒体采访时称，意方这一决定“荒谬且无用…"
