    "description": "新华社纽约9月15日电（记者刘亚南）由于通胀形势持续引发市场担忧和美国联邦储备委员会加息预期推动，美国10年期国债收益率在15日凌晨升至5.045%，为2007年7月以来的最高水平。 数据显示，美国10年期国债收益率在当日早间有所回落，但整体维持在5%上方。美国30年期国债收益率当日一度升至5.402%，为2007年6月以来高点。 芝加哥商品交易所美联储观察工具15日发布的信息显示，美联储将在16日结束的议息会议上宣布加息25个基点的概…",
