    "description": "新华社伊斯坦布尔9月15日电（记者王科文）据土耳其媒体报道，土最大城市伊斯坦布尔法提赫区一家货币兑换处15日发生枪击事件，造成3人死亡、1人受伤。 据报道，当天下午该货币兑换处经营者与一名顾客发生争执，随后冲突升级并引发枪击。警方和急救人员已将伤者送医救治，并控制一名嫌疑人。目前案件仍在调查中。",
    "content": "新华社伊斯坦布尔9月15日电（记者王科文）据土耳其媒体报道，土最大城市伊斯坦布尔法提赫区一家货币兑换处15日发生枪击事件，造成3人死亡、1人受伤。 据报道，当天下午该货币兑换处经营者与一名顾客发生争执，随后冲突升级并引发枪击。警方和急救人员已将伤者送医救治，并控制一名嫌疑人。目前案件仍在调查中。"
