    "content": "新华社乌鲁木齐9月15日电（记者高亢、孙少雄）2026上合组织数字经济论坛15日在新疆乌鲁木齐举行。国家数据局局长刘烈宏在论坛开幕式上表示，过去的一年，我国携手各方推动中国—上海合作组织数字经济合作平台建设，合作机制持续深化。一系列务实合作成果从愿景到项目落地见效，惠及各国人民。 刘烈宏建议，持续深化数据治理、数字基础设施互联互通、项目落地、数字人才培养等合作，携手以数据赋能人工智能创新发展，促进产业升级、贸易畅通、民生改善，走出一条符合上海合作组织实际的数字经济合作之路。 “数字化给经济发展带来了很多新机遇，推动…"
