    "content": "新华社长沙9月15日电（记者谢奔、刘芳洲）第五届北斗规模应用国际峰会15日在湖南株洲开幕。会上，由中国信息通信研究院编制的《北斗产业发展研究报告（2026年）》发布。报告显示，依托AI，北斗终端正由单一定位导航设备向智能感知、智能决策和智能作业的综合载体升级。 报告指出，当前，AI正赋能北斗向产品智能化、平台集约化、运营自主化、服务价值化演进。智能算法深度集成于北斗基带芯片、高精度接收机、车载及机载终端之中，传统北斗数据处理平台升级为AI赋能的全域时空智能底座。与此同时，北斗时空数据借助AI能力逐步成为数字经济关键…"
