    "author": "王晓梅,王雷",
    "description": "新华社开普敦9月15日电（记者王晓梅 王雷）为期两天的2026年非洲绿色氢能峰会15日在南非立法首都开普敦开幕。南非总统拉马福萨呼吁非洲国家抓住绿色氢能发展的历史性机遇，加强务实合作，以实现能源安全、推动脱碳进程并促进可持续发展。 拉马福萨在由该国电力和能源部长科西恩乔·拉莫豪帕代为宣读的开幕致辞中说，非洲拥有丰富的可再生能源、水资源和关键矿产，完全有条件成为全球绿色氢能产业重要枢纽。发展绿色氢能不仅关系到投资和新兴产业布局，也有助于缓…",
    "content": "新华社开普敦9月15日电（记者王晓梅 王雷）为期两天的2026年非洲绿色氢能峰会15日在南非立法首都开普敦开幕。南非总统拉马福萨呼吁非洲国家抓住绿色氢能发展的历史性机遇，加强务实合作，以实现能源安全、推动脱碳进程并促进可持续发展。 拉马福萨在由该国电力和能源部长科西恩乔·拉莫豪帕代为宣读的开幕致辞中说，非洲拥有丰富的可再生能源、水资源和关键矿产，完全有条件成为全球绿色氢能产业重要枢纽。发展绿色氢能不仅关系到投资和新兴产业布局，也有助于缓解非洲能源贫困、创造就业，并推动公正能源转型。非洲应抓住这一千载难逢的机遇，加快…"
