    "content": "新华社东京9月15日电（记者陈泽安 蓝建中）据日本共同社15日晚报道，日本航空自卫队推测，当天下午失联的“全球鹰”无人侦察机已坠毁。 当地时间15日13时（北京时间15日12时）左右，日本航空自卫队一架“全球鹰”无人侦察机在鸟取县附近海域上空失联。日本自卫队和海上保安厅随后展开搜寻。共同社报道称，搜寻过程中，在鸟取县附近海域发现了疑似失联无人机机体的漂浮物。 这架无人机隶属于位于日本青森县的三泽基地。据日本航空自卫队消息，该无人机于当地时间10时20分（北京时间9时20分）左右从三泽基地起飞。在通信中断前，曾发生通…"
