    "author": "郭鑫惠",
    "description": "新华社苏瓦9月15日电（记者郭鑫惠）斐济政府15日宣布艾滋病疫情已经构成该国国家危机，并启动全政府层面的协同应对措施，以遏制艾滋病病毒感染病例大幅攀升的势头，保护社区民众。 斐济卫生部长阿托尼奥·拉拉巴拉武当天召开新闻发布会说，2025年斐济新增艾滋病病毒感染病例2016例，这一数字是2019年的16倍。据估计，目前每60名成年人中就有1人感染艾滋病病毒，而五年前这一比例为167分之一；在孕妇群体中，每100人中就有2人感染艾滋病病毒。…",
    "content": "新华社苏瓦9月15日电（记者郭鑫惠）斐济政府15日宣布艾滋病疫情已经构成该国国家危机，并启动全政府层面的协同应对措施，以遏制艾滋病病毒感染病例大幅攀升的势头，保护社区民众。 斐济卫生部长阿托尼奥·拉拉巴拉武当天召开新闻发布会说，2025年斐济新增艾滋病病毒感染病例2016例，这一数字是2019年的16倍。据估计，目前每60名成年人中就有1人感染艾滋病病毒，而五年前这一比例为167分之一；在孕妇群体中，每100人中就有2人感染艾滋病病毒。 拉拉巴拉武说，作为国家应对行动的一部分，斐济全国四个行政区均可提供免费且保密的…"
