    "title": "一条鱼串起“蓝色粮仓”产业链",
    "link": "http://www.news.cn/20260915/0b7ee2b8245f477ea7fb4f89d30bf533/c.html",
    "pub_date": "2026-09-15 20:52:33",
    "author": "王欢",
    "description": "新华社济南9月15日电（记者王欢）黄海之上，一座大型深远海养殖网箱矗立海面，数万尾三文鱼在清澈海水中游动。这是可移动柱稳式坐底养殖网箱财金“海上粮仓壹号”，养殖水体约6万立方米，年产三文鱼可达1000吨。 距此10海里许，位于山东省日照市岚山区的万泽丰三文鱼产业科创基地内，工作人员通过中控大屏实时观测“海上粮仓”系列和“深蓝”系列网箱鱼群状态，开展精准投喂，并对台风、水质异常等风险进行预警，协同海上养殖人员保障生产安全。 “远程中控室是…",
    "content": "新华社济南9月15日电（记者王欢）黄海之上，一座大型深远海养殖网箱矗立海面，数万尾三文鱼在清澈海水中游动。这是可移动柱稳式坐底养殖网箱财金“海上粮仓壹号”，养殖水体约6万立方米，年产三文鱼可达1000吨。 距此10海里许，位于山东省日照市岚山区的万泽丰三文鱼产业科创基地内，工作人员通过中控大屏实时观测“海上粮仓”系列和“深蓝”系列网箱鱼群状态，开展精准投喂，并对台风、水质异常等风险进行预警，协同海上养殖人员保障生产安全。 “远程中控室是网箱的管控中枢，依靠水下摄像头、生物量系统和各类传感器，将海上环境、鱼群等数据实…"
