    "author": "王晓梅,王雷",
    "description": "新华社开普敦9月15日电（记者王晓梅 王雷）南非财政部15日宣布，南非与金砖国家新开发银行签署一项10亿美元贷款协议，以升级改造该国多个大都市的市政服务基础设施。 南非财政部在当天发表的声明中说，这笔贷款将助力南非政府为民众提供更优质的市政服务，建设更完善、更可持续发展的城市。升级改造大都市市政服务基础设施是政府市政服务改革计划的一部分。该计划重点涵盖供水与卫生、电力与能源以及垃圾处理等领域。 总部位于上海的新开发银行2015年7月21…",
    "content": "新华社开普敦9月15日电（记者王晓梅 王雷）南非财政部15日宣布，南非与金砖国家新开发银行签署一项10亿美元贷款协议，以升级改造该国多个大都市的市政服务基础设施。 南非财政部在当天发表的声明中说，这笔贷款将助力南非政府为民众提供更优质的市政服务，建设更完善、更可持续发展的城市。升级改造大都市市政服务基础设施是政府市政服务改革计划的一部分。该计划重点涵盖供水与卫生、电力与能源以及垃圾处理等领域。 总部位于上海的新开发银行2015年7月21日正式开业，是由金砖国家共同倡议建立的国际性金融机构，旨在为金砖国家等新兴经济体…"
