    "description": "9月13日至15日，应中共中央对外联络部邀请，由30个国家的政党媒体和主流媒体代表组成的媒体研修班到访浙江杭州。在浙江省非物质文化遗产馆、良渚古城遗址公园等地，通过实地探访、互动体验和对话交流，近距离感受中华文化的博大精深与独特魅力。 记者：宋立峰、郑可意 新华社音视频部制作",
    "content": "9月13日至15日，应中共中央对外联络部邀请，由30个国家的政党媒体和主流媒体代表组成的媒体研修班到访浙江杭州。在浙江省非物质文化遗产馆、良渚古城遗址公园等地，通过实地探访、互动体验和对话交流，近距离感受中华文化的博大精深与独特魅力。 记者：宋立峰、郑可意 新华社音视频部制作"
