    "content": "新华社北京9月15日电（记者邵艺博、吴梦桐）外交部发言人郭嘉昆15日表示，人工智能发展和治理需要践行真正的多边主义，通过世界各国共同参与，形成具有广泛共识的全球治理框架。 有记者问：外交部14日就美国科技企业负责人呼吁“放缓”发展人工智能前沿技术作出回应，能否进一步阐释具体看法？中方如何评估人工智能可能被用于制造生物武器等风险？ “我们注意到美国人工智能业界人士近期发表的言论。”郭嘉昆表示，人工智能技术发展越是一日千里，向上向善、造福人类的方向越要正确锚定，监管治理的尺度越要精准把握，防范失控的措施越要及时完善。 …"
