    "content": "近日，中共中央总书记、国家主席、中央军委主席习近平给福建省“漳州110”全体队员回信，对他们予以亲切勉励并提出殷切期望。 上世纪90年代，为方便群众拨打报警电话，同时提高出警速度，福建省漳州市公安局创立了“110报警服务台”，并建立起快速反应机制。开启了维护治安与服务群众并重的先河，“110”这个号码就此为百姓所熟知。 “远亲不如近邻，近邻不如漳州110”，这句赞誉，是群众发自内心的褒奖，更是“漳州110”为民初心的生动印证。 “漳州110”始终牢记嘱托，把“人民的110”这块金字招牌擦得更亮。 &nbsp; 策划…"
