    "link": "http://www.news.cn/20260915/6f5a9864caec435782c1d33dafa862e7/c.html",
    "pub_date": "2026-09-15 20:27:47",
    "author": "张阳,李思远",
    "description": "新华社武汉9月15日电（记者张阳、李思远）记者15日从水利部长江水利委员会获悉，2026年三峡水库促进产漂流性卵鱼类自然繁殖生态调度试验响应期间，宜都、沙市江段产漂流性卵鱼类卵径流量分别达669亿粒、604亿粒，其中四大家鱼卵径流量为435亿粒、301亿粒，监利江段鱼苗总量达2424亿尾。宜都江段四大家鱼产卵量、监利江段鱼苗总量均创新高。 据了解，以青鱼、草鱼、鲢鱼、鳙鱼四大家鱼为代表的产漂流性卵鱼类要实现自然繁殖，需要具备持续涨水、适…",
    "content": "新华社武汉9月15日电（记者张阳、李思远）记者15日从水利部长江水利委员会获悉，2026年三峡水库促进产漂流性卵鱼类自然繁殖生态调度试验响应期间，宜都、沙市江段产漂流性卵鱼类卵径流量分别达669亿粒、604亿粒，其中四大家鱼卵径流量为435亿粒、301亿粒，监利江段鱼苗总量达2424亿尾。宜都江段四大家鱼产卵量、监利江段鱼苗总量均创新高。 据了解，以青鱼、草鱼、鲢鱼、鳙鱼四大家鱼为代表的产漂流性卵鱼类要实现自然繁殖，需要具备持续涨水、适宜流速和20℃以上水温等条件。今年5月至7月，长江水利委员会联合多家单位，开展三…"
