    "author": "王俊杰,吕京笏,张建",
    "description": "近日，习近平总书记给福建省“漳州110”全体队员回信，对他们予以亲切勉励并提出殷切期望，彰显了人民领袖对人民公安的高度重视、对人民安全的深切关心。 “漳州110”是公安系统的一张亮丽名片，1990年以来创新并持续优化110报警服务快速反应机制，在打击犯罪、维护治安、服务群众等方面发挥重要作用，是全国公安机关优秀基层单位代表，被誉为“人民的保护神”。习近平总书记在福建工作期间曾3次到警队考察，指导推动“漳州110”建设发展。 岁月静好，有…",
