    "author": "段菁菁",
    "description": "新华社杭州9月15日电（记者段菁菁）2026年中国经济社会论坛15日在杭州举行，85位中外嘉宾围绕“完善全球治理体系，迈向人类命运共同体”深入交流。全国政协副主席兼秘书长、中国经济社会理事会主席王东峰出席并发表主旨讲话。 王东峰表示，习近平主席提出的全球治理倡议，是继全球发展倡议、全球安全倡议、全球文明倡议之后，中国贡献的又一重要国际公共产品，为推动构建人类命运共同体提供了战略支撑。要加强治国理政经验交流，坚持人类命运共同体理念，坚持共…",
    "content": "新华社杭州9月15日电（记者段菁菁）2026年中国经济社会论坛15日在杭州举行，85位中外嘉宾围绕“完善全球治理体系，迈向人类命运共同体”深入交流。全国政协副主席兼秘书长、中国经济社会理事会主席王东峰出席并发表主旨讲话。 王东峰表示，习近平主席提出的全球治理倡议，是继全球发展倡议、全球安全倡议、全球文明倡议之后，中国贡献的又一重要国际公共产品，为推动构建人类命运共同体提供了战略支撑。要加强治国理政经验交流，坚持人类命运共同体理念，坚持共商共建共享的全球治理观，坚持和弘扬全人类共同价值，践行真正的多边主义，为完善全球…"
