    "content": "9月15日，在瑞士日内瓦世界贸易组织总部，世贸组织总干事伊维拉在2026年公共论坛上发言。新华社记者 连漪 摄 新华社日内瓦9月15日电（记者焦倩）世界贸易组织15日发布《2026世界贸易报告》指出，全球贸易政策和世贸组织正面临多边贸易体制建立以来最严重且持续的挑战，若迟迟不推动贸易体系现代化，全球产出最多可能下降10%；通过改革强化多边贸易体制将促进全球经济发展。 世贸组织这份最新年度重点报告题为“处于关键时刻的世界贸易体制”，梳理了多边贸易体制数十年来取得的成果以及当前面临的挑战。报告指出，该体制助力降低贸易壁…"
