    "content": "新华社东京9月15日电（记者蓝建中 李诗萌）日本10年期国债收益率15日一度升至3.035%，创近30年来新高。 市场预期美联储会为抑制物价上涨而加息，美债遭到抛售，美国10年期国债收益率14日盘中突破5%。美国长期利率走高传导至日本国债市场。 业内人士指出，原油价格居高不下，同样助推长期利率上行。日本能源依赖进口，市场担忧国内通胀加速拖累经济，导致抛售日本国债的情绪扩散。此外，由于对高市政府的积极财政政策引发财政恶化的担忧加深，投资者也减少了国债买入。 瑞士百达集团日本公司高级研究员大槻奈那指出，今年以来，长期利…"
